struct DocState: Codable, Equatable {           // value-type memento
    var text: String
    var caret: Int
}

final class Editor {
    private(set) var state = DocState(text: "", caret: 0)
    private var history: [DocState] = []        // caretaker
    func save() { history.append(state) }
    func undo() { if let previous = history.popLast() { state = previous } }
}

