final class Editor {
    private(set) var state = DocState(text: "", caret: 0)
    private let undoManager = UndoManager()
    func setText(_ text: String) {
        let previous = state                     // memento captured in the closure
        undoManager.registerUndo(withTarget: self) { $0.state = previous }
        state.text = text
    }
    func undo() { undoManager.undo() }
}
